#include "rinkfit/joint_actual_trial_probe_v1.hpp"
#include "rinkfit/joint_solver_metric_v1.hpp"
#include "rinkfit/joint_compact_state.hpp"
#include <iostream>
using namespace rinkfit;
static void require(bool x,const char*m){if(!x)throw std::runtime_error(m);}
struct Toy final:ceres::SizedCostFunction<2,2,2>{bool Evaluate(double const*const*p,double*r,double**j)const override{r[0]=2*p[0][0]+p[1][0]-1.;r[1]=p[0][1]+3*p[1][1]-1.;if(j){if(j[0]){j[0][0]=2;j[0][1]=0;j[0][2]=0;j[0][3]=1;}if(j[1]){j[1][0]=1;j[1][1]=0;j[1][2]=0;j[1][3]=3;}}return true;}};
struct Delegate final:ceres::EvaluationCallback{double*x,*y;std::array<double,4>last{};int calls=0;Delegate(double*a,double*b):x(a),y(b){}void PrepareForEvaluation(bool,bool)override{last={x[0],x[1],y[0],y[1]};++calls;}};
int main(int argc,char**argv){try{require(argc==2,"OUT");for(int clipped=0;clipped<2;++clipped){
 JointEventModel m;m.blocks.resize(3);m.blocks[0].name="scene";m.blocks[0].values={.5,.3,.1,.02,.01};m.blocks[0].scales=std::vector<double>(5,.02);
 for(int i=1;i<=2;++i){auto&v=m.blocks[i];v.name=i==1?"shot/toy/control":"print_vertex/toy";v.values={0.,0.};v.scales={.02,.02};}
 m.source_json={{"blocks",eventio::Json::array()},{"linear_control_manifolds",eventio::Json::array()}};for(const auto&v:m.blocks)m.source_json["blocks"].push_back({{"name",v.name},{"values",v.values}});
 JointPacket packet;packet.source_hash="toy_current_only";packet.source_json={{"runtime_current_input_v1",true}};
 JointALBuilder b(std::move(m),std::move(packet),true,false,true);double*x=b.core.model.blocks[1].values.data(),*y=b.core.model.blocks[2].values.data();Delegate delegate(x,y);
 if(!clipped){JointCompactAcceptedState saved(b);const auto only=std::filesystem::path(argv[1])/"failure_only";std::filesystem::create_directories(only);configure_joint_actual_factor_failure_audit_v1(true,only);int lookups=0;joint_actual_factor_failure_audit_v1().resolve_accepted_base=[&](const double*address,int size){++lookups;JointActualFactorFailureAuditV1::Base v;v.size=size;saved.saved_parameter_view_v1(address,size,&v.name,&v.value);return v;};x[0]=.025;require(lookups==0,"failure-only resolver scanned a successful state");joint_actual_factor_failure_v1([&](eventio::Json&r){r["factor"]="failure_only_current_accepted_base";append_joint_actual_failure_parameter_v1(r,x,x,2,"toy");});const auto capture=eventio::read_json(only/"actual_first_factor_failure.json");require(lookups==1&&capture.at("parameters")[0].at("base_values")==eventio::Json::array({0.,0.})&&capture.at("parameters")[0].at("actual_values")==eventio::Json::array({.025,0.})&&capture.at("parameters")[0].at("base_source")=="current_complete_accepted_state","failure-only capture lost the actual accepted base or aliased a trial");x[0]=0.;configure_joint_actual_factor_failure_audit_v1(false,only);}
 const auto out=std::filesystem::path(argv[1])/std::to_string(clipped);std::filesystem::create_directories(out);configure_joint_actual_factor_failure_audit_v1(true,out);JointActualTrialProbeV1 probe(b,&delegate,out);
 ceres::Problem::Options po;po.evaluation_callback=&probe;ceres::Problem p(po);p.AddResidualBlock(new Toy,nullptr,x,y);auto*original_x=new ceres::SubsetManifold(2,{1});p.SetManifold(x,original_x);const double inv=1./std::sqrt(2.);p.SetManifold(y,new JointLinearControlManifold({{"ambient_size",2},{"tangent_size",1},{"basis",{{inv},{clipped?-inv:inv}}}}));if(clipped)p.SetParameterLowerBound(y,1,0.);
 JointSolverMetricV1 metric;metric.prepare(b,p);probe.arm(p);
 const double base[2]={0.,0.},step[1]={2.};require(p.GetManifold(x)->Plus(base,step,x),"metric x Plus");require(p.GetManifold(y)->Plus(base,step,y),"metric y Plus");if(clipped)y[1]=0.;probe.PrepareForEvaluation(false,true);
 int failure_records=0;joint_actual_factor_failure_v1([&](eventio::Json&r){++failure_records;r["factor"]="toy_actual_failure";append_joint_actual_failure_parameter_v1(r,x,x,2,"toy");});joint_actual_factor_failure_v1([&](eventio::Json&){++failure_records;});require(failure_records==1,"first actual failure emitted more than once");
 // The accepted state can differ from both the base and recorded trial.
 x[0]=.01;x[1]=0.;y[0]=.02;y[1]=clipped?0.:.01;const std::array<double,4>accepted{x[0],x[1],y[0],y[1]};metric.restore(p);p.SetManifold(y,nullptr);
 const auto report=probe.analyze(p,1);require(std::array<double,4>{x[0],x[1],y[0],y[1]}==accepted,"probe changed accepted numeric state");require(p.GetManifold(x)==original_x&&p.GetManifold(y)==nullptr,"probe left solver metric or gauge installed");require(delegate.last==accepted,"probe left cache at diagnostic point");require(report.at("ALL_direction_only_probes").size()==2,"probe performed wrong number of extra cost probes");require(report.at("extra_Solver_calls")==0&&report.at("full_raw_exports_written")==0,"probe used heavyweight side path");
 const auto mismatches=report.at("manifold_roundtrip_mismatch_count").get<std::size_t>();require(clipped?mismatches==1:mismatches==0,"actual box/chart mismatch not detected");
 require(std::filesystem::file_size(out/"actual_solver_base.f64")==4*sizeof(double)&&std::filesystem::file_size(out/"actual_solver_first_proposal.f64")==4*sizeof(double),"compact actual proposal points incomplete");const auto failed=eventio::read_json(out/"actual_first_factor_failure.json");require(failed.at("parameters")[0].at("base_values")==eventio::Json::array({0.,0.}),"failure omitted actual arm-point values");for(const auto&i:report.at("ALL_direction_only_probes"))require(i.at("scaled_Plus_valid")==true&&i.at("Problem_Evaluate_called")==true,"probe still conflates mapping with evaluation");
 if(!clipped){const double prediction=report.at("linear_predictions").at("ALL");require(prediction<0,"toy solver-chart direction is not descent");for(const auto&item:report.at("ALL_direction_only_probes")){require(item.at("valid"),"toy directional cost invalid");const double slope=item.at("directional_slope");require(std::abs(slope-prediction)<1e-4,"solver chart JTr does not match actual cost slope");}}
 eventio::atomic_json(out/"result.json",report);
 }std::cout<<"narrow actual proposal: solver-chart slope, box/chart mismatch, accepted numeric/manifold/cache restoration passed; no Solver/full source load"<<std::endl;return 0;}catch(const std::exception&e){std::cerr<<e.what()<<std::endl;return 1;}}
